{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A whole-person practice</title>
  <meta name="description" content="Integrative, evidence-minded care that centers your life, rhythms, and choices. Educational consultations, personalized plans, and ongoing support.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="theme-earthy">
  <header class="site-header">
    <div class="wrap header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <button class="nav-toggle" aria-label="Toggle navigation">☰</button>
      <nav class="primary-nav" aria-label="Main navigation">
        <ul>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="conditions.html">Common Concerns</a></li>
          <li><a href="approach.html">How we work</a></li>
          <li><a href="pricing.html">Invest</a></li>
          <li><a href="about.html">Our story</a></li>
          <li><a href="book.html">Visit</a></li>
          <li><a href="contact.html">Connect</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <svg class="hero-pattern" preserveAspectRatio="none" viewBox="0 0 800 400" aria-hidden="true">
        <defs>
          <linearGradient id="g1" x1="0" x2="1">
            <stop offset="0" stop-color="#F6E7D9" />
            <stop offset="1" stop-color="#E7CEB8" />
          </linearGradient>
        </defs>
        <rect width="100%" height="100%" fill="url(#g1)" />
        <path d="M0 120 C150 40 300 200 450 120 C600 40 750 200 800 120 L800 400 L0 400 Z" fill="#EAD6C1" opacity="0.45" />
        <g transform="translate(30,20)" fill="#CBB29A" opacity="0.12">
          <ellipse cx="60" cy="60" rx="60" ry="28" />
          <ellipse cx="260" cy="80" rx="90" ry="30" />
          <ellipse cx="520" cy="40" rx="70" ry="26" />
        </g>
      </svg>

      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">A gentler path to balanced living</h1>
          <p class="subtitle">{{TAGLINE}} — nurturing body, mind, and daily rhythms through thoughtful, evidence-informed care.</p>
          <p class="meta">With {{PRACTITIONER_NAME}}, {{CREDENTIALS}} — serving {{CITY}}, {{STATE}}</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">Meet the practitioner</a>
          </div>
        </div>
        <aside class="hero-card" aria-hidden="false">
          <div class="card-inner">
            <p class="small">Next available visits and learning series</p>
            <ul class="mini-list">
              <li>Intro visit — 60 min</li>
              <li>Follow-up — 30–45 min</li>
              <li>Monthly group: Foundations of Rest</li>
            </ul>
            <a class="btn small" href="book.html">Book a visit</a>
          </div>
        </aside>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof wrap" id="proof">
      <h2 class="section-title">Quiet words from people we’ve walked with</h2>
      <div class="testimonials">
        <figure class="testimonial">
          <blockquote>"A steady, listening approach—helped me reframe stress without pressure to be perfect."</blockquote>
          <figcaption>— M.L., teacher</figcaption>
        </figure>
        <figure class="testimonial">
          <blockquote>"Practical steps that honored my routine and values. I learned to sleep better without harsh fixes."</blockquote>
          <figcaption>— R., freelance designer</figcaption>
        </figure>
        <figure class="testimonial">
          <blockquote>"Clear explanations and a plan that felt like it was designed for my whole life."</blockquote>
          <figcaption>— K., parent</figcaption>
        </figure>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits" id="benefits">
      <div class="wrap">
        <h2 class="section-title">Where this work helps most</h2>
        <p class="lead">Education, gentle interventions, and coordinated plans for everyday resilience.</p>
        <ul class="benefit-grid">
          <li>
            <strong>Understand your story</strong>
            <p>Learn how lifestyle, environment, and history shape symptoms and vitality.</p>
          </li>
          <li>
            <strong>Practical rhythms</strong>
            <p>Simple, sustainable steps for sleep, meals, and stress that fit your life.</p>
          </li>
          <li>
            <strong>Personalized plans</strong>
            <p>Guided support tailored to priorities, not one-size-fits-all directives.</p>
          </li>
          <li>
            <strong>Informed pathways</strong>
            <p>When useful, we discuss labs and referrals as part of your educational plan.</p>
          </li>
        </ul>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process wrap" id="process">
      <h2 class="section-title">How we move forward together</h2>
      <ol class="steps">
        <li>
          <h3>1 — Intake & narrative</h3>
          <p>We begin with an attentive intake: medical history, priorities, and day-to-day patterns. This is the educational foundation.</p>
        </li>
        <li>
          <h3>2 — A gently tailored plan</h3>
          <p>Collaborative, practical recommendations—behavioral, nutritional, mind-body practices, supplements when appropriate—to support whole-person balance.</p>
        </li>
        <li>
          <h3>3 — Optional learning & labs</h3>
          <p>We may suggest targeted labs or resources to inform choices. Labs are optional and always explained with context.</p>
        </li>
        <li>
          <h3>4 — Follow-up & adjustment</h3>
          <p>Follow-ups focus on refinement, education, and sustainable progression rather than quick fixes.</p>
        </li>
      </ol>
    </section>

    <!-- FAQ -->
    <section class="faq wrap" id="faq">
      <h2 class="section-title">Questions people often ask</h2>
      <div class="qa">
        <details>
          <summary>Is this a replacement for primary or emergency care?</summary>
          <p>No. We work with your existing healthcare team when needed. We do not provide emergency services or guaranteed cures—our focus is education and coordinated support.</p>
        </details>
        <details>
          <summary>Do you use medications or supplements?</summary>
          <p>When appropriate, we discuss evidence-based options and the reasoning behind them. Decisions are collaborative and individualized.</p>
        </details>
        <details>
          <summary>What can I expect in the first visit?</summary>
          <p>An extended conversation to map priorities, discuss goals, and outline the first steps you can take right away.</p>
        </details>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead-magnet wrap" id="guide">
      <div class="magnet-inner">
        <div class="magnet-copy">
          <h2 class="section-title">Free guide: Foundations of Daily Resilience</h2>
          <p class="lead">A short companion of small, evidence-minded habits for calmer days. Practical suggestions you can try within a week.</p>
        </div>
        <form id="leadForm" class="magnet-form" aria-label="Sign up for guide">
          <label for="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name">
          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@example.com" required>
          <input type="hidden" name="source" value="homepage_guide">
          <button class="btn primary" type="submit">Send the guide</button>
          <p class="fineprint">We respect your privacy. No spam — unsubscribe anytime.</p>
        </form>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta wrap" id="cta">
      <div class="cta-inner">
        <h2 class="section-title">Ready to begin a thoughtful approach?</h2>
        <p>Schedule a conversation to explore an educational, whole-person plan that fits your life.</p>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Questions first?</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-inner">
      <div class="contact">
        <p class="brand">{{BUSINESS_NAME}}</p>
        <p>{{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <nav class="footer-nav" aria-label="Footer">
        <ul>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="approach.html">How we work</a></li>
          <li><a href="book.html">Visit</a></li>
          <li><a href="privacy.html">Privacy</a></li>
        </ul>
      </nav>
    </div>
  </footer>

  <!-- Decorative pattern for CSS fallback -->
  <svg width="0" height="0" style="position:absolute;left:-9999px;" aria-hidden="true">
    <defs>
      <pattern id="p1" width="40" height="40" patternUnits="userSpaceOnUse">
        <rect width="40" height="40" fill="#F6E7D9" />
        <path d="M0 20 Q20 0 40 20" stroke="#E7CEB8" stroke-width="1" fill="none" opacity="0.4" />
      </pattern>
    </defs>
  </svg>
</body>
</html>"} 
