{"path":"assets/css/styles.css","content":"/* Earthy warm theme — no external fonts */
:root{
  --bg:#FBF7F2;
  --muted:#7A6756;
  --accent:#8CA58C;
  --accent-2:#C59A6B;
  --card:#FFF7EE;
  --shadow: rgba(18,15,12,0.06);
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,'Helvetica Neue',Arial;line-height:1.45;color:var(--muted);background:var(--bg);}
.wrap{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);border-bottom:1px solid rgba(0,0,0,0.03);position:sticky;top:0;backdrop-filter: blur(4px);z-index:30}
.header-inner{display:flex;align-items:center;justify-content:space-between;padding:0.75rem 1rem}
.brand{font-weight:700;color:#3F3428;text-decoration:none}
.nav-toggle{display:none;background:none;border:0;font-size:1.25rem}
.primary-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:1rem}
.primary-nav a{text-decoration:none;color:var(--muted);padding:0.35rem 0.5rem;border-radius:6px}
.primary-nav a:hover{background:rgba(140,165,140,0.08)}

/* HERO */
.hero{position:relative;overflow:hidden;padding:3rem 0 2rem}
.hero-pattern{position:absolute;inset:0;width:100%;height:100%;opacity:0.95}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:2rem;align-items:stretch;position:relative}
.hero-copy{padding:3rem 1rem}
.title{font-size:clamp(1.6rem,3.5vw,2.4rem);margin:0 0 0.5rem;color:#3E2F25}
.subtitle{margin:0 0 1rem;color:#5f4f43}
.meta{font-size:0.9rem;color:#6b5846}
.hero-ctas{margin-top:1rem;display:flex;gap:0.75rem}
.btn{display:inline-block;text-decoration:none;padding:0.6rem 1rem;border-radius:8px;border:1px solid transparent;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.btn.ghost{background:transparent;border:1px solid rgba(60,50,40,0.06);color:var(--muted)}
.btn.small{padding:0.4rem 0.7rem;font-size:0.9rem}

.hero-card{background:var(--card);border-radius:12px;padding:1rem;box-shadow:0 8px 18px var(--shadow)}
.mini-list{margin:0;padding:0 0 0 1.2rem}
.mini-list li{margin:0.35rem 0}

/* SOCIAL PROOF */
.social-proof{padding:2rem 0}
.testimonials{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}
.testimonial{background:linear-gradient(180deg,#fffaf6, #fff2e7);padding:1rem;border-radius:10px}
.testimonial blockquote{margin:0 0 0.5rem;font-style:italic;color:#5b4a3b}
.testimonial figcaption{font-size:0.85rem}

/* BENEFITS */
.benefits{padding:2.5rem 0}
.benefit-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;list-style:none;padding:0;margin:1rem 0 0}
.benefit-grid li{background:white;padding:1rem;border-radius:10px;border:1px solid rgba(0,0,0,0.03)}

/* PROCESS */
.process{padding:2.5rem 0}
.steps{counter-reset:step;list-style:none;padding:0;display:grid;gap:1rem}
.steps li{display:block;background:linear-gradient(180deg,#fff, #fff6f1);padding:1rem;border-radius:10px}
.steps li h3{margin:0 0 0.5rem}

/* FAQ */
.faq details{background:white;padding:0.9rem;border-radius:8px;margin:0.6rem 0}
.faq summary{cursor:pointer;font-weight:600}

/* LEAD MAGNET */
.lead-magnet{padding:2.5rem 0}
.magnet-inner{display:flex;gap:2rem;align-items:center}
.magnet-copy{flex:1}
.magnet-form{width:320px;background:var(--card);padding:1rem;border-radius:10px;box-shadow:0 8px 20px var(--shadow);display:flex;flex-direction:column;gap:0.5rem}
.magnet-form input{padding:0.6rem;border-radius:6px;border:1px solid rgba(0,0,0,0.06)}
.fineprint{font-size:0.8rem;color:#7b6a5b}

/* CTA */
.final-cta{padding:2.5rem 0;text-align:center}
.cta-actions{display:flex;gap:1rem;justify-content:center;margin-top:1rem}
.btn.large{padding:0.9rem 1.4rem;font-size:1rem}

/* FOOTER */
.site-footer{border-top:1px solid rgba(0,0,0,0.04);background:linear-gradient(180deg,transparent, rgba(250,246,241,0.6));padding:1.5rem 0}
.footer-inner{display:flex;justify-content:space-between;align-items:center}
.footer-nav ul{list-style:none;display:flex;gap:1rem;padding:0;margin:0}
.footer-nav a{text-decoration:none;color:var(--muted)}

/* Responsive */
@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr}
  .nav-toggle{display:inline-block}
  .primary-nav{display:none}
  .primary-nav.open{display:block;position:absolute;right:1rem;top:64px;background:var(--bg);padding:0.5rem;border-radius:8px;box-shadow:0 8px 20px var(--shadow)}
  .primary-nav ul{flex-direction:column}
  .wrap{padding:1rem}
  .magnet-inner{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // nav toggle for small screens
  var toggle=document.querySelector('.nav-toggle');
  var nav=document.querySelector('.primary-nav');
  if(toggle && nav){
    toggle.addEventListener('click',function(){
      nav.classList.toggle('open');
    });
  }

  // smooth internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var targetId=this.getAttribute('href').slice(1);
      var el=document.getElementById(targetId);
      if(el){
        e.preventDefault();
        el.scrollIntoView({behavior:'smooth',block:'start'});
      }
    });
  });

  // lead magnet form handling
  var form=document.getElementById('leadForm');
  if(form){
    form.addEventListener('submit',function(e){
      e.preventDefault();
      var email=form.querySelector('input[type="email"]').value.trim();
      var name=form.querySelector('input[name="name"]').value.trim();
      if(!email || !email.includes('@')){
        alert('Please provide a valid email.');
        return;
      }
      // Simulated success — in a real site this would post to an API
      localStorage.setItem('lead_'+email,JSON.stringify({name:name||null,email:email,time:Date.now()}));
      form.innerHTML='<p style="margin:0 0 0.5rem;font-weight:600">Thanks — your guide is on its way to '+email+'</p>'+
                     '<p style="margin:0;color:#6b5846">Check your inbox. If you don\'t see it, check spam or contact us at {{EMAIL}}</p>';
    });
  }

  // lightweight accessibility enhancement: focus outlines
  document.addEventListener('keydown',function(e){
    if(e.key==='Tab') document.body.classList.add('show-focus');
  });
});"} 
